import { test, expect, users } from '../fixtures';

/**
 * UIP-773 — Checkout: user can complete purchase of a cart item on SauceDemo.
 * Generated by the Test Design & Scaffold Agent pattern (one test per acceptance criterion).
 * Tag @checkout = module tag used by the Verify Fixed Bugs sub-process (--grep @checkout).
 */
test.describe('UIP-773 checkout @checkout', () => {
  test('AC1: adding a product shows cart badge 1 @UIP-773', async ({ loginPage, inventoryPage }) => {
    await loginPage.goto();
    await loginPage.login(users.standard, users.password);
    await inventoryPage.expectLoaded();

    await inventoryPage.addToCart('sauce-labs-backpack');

    await expect(inventoryPage.cartBadge).toHaveText('1');
  });

  test('AC2: completing checkout shows order confirmation @UIP-773', async ({ loginPage, inventoryPage, checkoutPage }) => {
    await loginPage.goto();
    await loginPage.login(users.standard, users.password);
    await inventoryPage.addToCart('sauce-labs-backpack');
    await inventoryPage.openCart();

    await checkoutPage.start();
    await checkoutPage.fillInfo({ firstName: 'QA', lastName: 'Agent', postalCode: '54000' });
    await checkoutPage.finish();

    await expect(checkoutPage.completeHeader).toHaveText('Thank you for your order!');
  });

  test('AC3: empty postal code blocks checkout with an error @UIP-773', async ({ loginPage, inventoryPage, checkoutPage }) => {
    await loginPage.goto();
    await loginPage.login(users.standard, users.password);
    await inventoryPage.addToCart('sauce-labs-backpack');
    await inventoryPage.openCart();

    await checkoutPage.start();
    await checkoutPage.fillInfo({ firstName: 'QA', lastName: 'Agent', postalCode: '' });

    await expect(checkoutPage.error).toHaveText('Error: Postal Code is required');
  });

  test('AC4: locked-out user cannot log in @UIP-773', async ({ loginPage, page }) => {
    await loginPage.goto();
    await loginPage.login(users.lockedOut, users.password);

    await expect(loginPage.error).toHaveText('Epic sadface: Sorry, this user has been locked out.');
    await expect(page).not.toHaveURL(/inventory\.html/);
  });
});
